insert into levels(code,track,cargo,ordem,reqs) values('T1','tecnica','Estagiário I (Aprendiz)',0,'["Foco: integração cultural, observação assistida e apoio no acolhimento", "Cursando o 1º ou 2º período de Bacharelado em Educação Física", "Auxilia no suporte e no acolhimento de alunos", "Observa as técnicas de abordagem e correção", "Zela pela organização dos pesos e acessórios", "Não prescreve treinos de forma autônoma (atuação sempre supervisionada por profissional com CREF)"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T2','tecnica','Estagiário II',1,'["Foco: co-condução de avaliações físicas simplificadas e apoio à ordem técnica do salão", "A partir do 3º período de Bacharelado, ou experiência prática validada pela coordenação", "Participa das reuniões de alinhamento metodológico", "Auxilia na montagem de programas de treino (sob validação)", "Orienta os estagiários de nível I", "Contribui com sugestões baseadas em evidências científicas", "Passagem T1 → T2: integração concluída e domínio dos processos básicos; mínimo de 3 meses como T1"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T3','tecnica','Estagiário Sênior (Mentor de Cultura)',2,'["Foco: mentoria entre pares dos novos estagiários; elo com o Coordenador", "Faz o alinhamento operacional dos estagiários I e II no turno", "Mentoria dos novos estagiários e atendimento (mentora de cultura)", "Desenvolve minutas de treinos personalizados para revisão do professor", "Inspeção rotineira dos aparelhos e notificação de necessidades preventivas e corretivas", "Em preparação final para o cargo de professor", "Passagem T2 → T3: avaliações simplificadas com qualidade e perfil de mentor; mínimo de 6 meses como T2"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T4','tecnica','Professor Trainee',3,'["Foco: 90 dias pós-formatura com prescrição acompanhada e CREF regularizado", "Bacharelado em Educação Física concluído", "CREF ativo", "Aprovado no exame prático interno"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T5','tecnica','Professor Júnior',4,'["Foco: prescrição autônoma para iniciantes e intermediários; atendimento de salão exemplar", "Passagem T4 → T5: 90 dias acompanhado(a) por Professor Sênior ou RT, sem pendências; mínimo de 3 meses", "CREF ativo", "Atua com autonomia no salão; pode assumir a função de Responsável de Turno (exemplo do plano: turno da noite)", "Responsável de Turno é função, não cargo: em cada faixa, o profissional mais sênior presente responde pelo turno"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T6','tecnica','Professor Pleno',5,'["Foco: especialização (ex.: hipertrofia feminina, seniores, preparação física); lidera projetos e workshops", "Especialização comprovada (ex.: hipertrofia feminina)", "Projeto ou workshop entregue", "Substituto(a) definido(a) nas faltas e férias", "Tempo mínimo de 12 meses como T5"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('T7','tecnica','Professor Sênior (Referência Técnica)',6,'["Foco: formação dos juniores, auditoria interna de qualidade e protocolos", "Referência técnica da equipe", "Forma os juniores e audita a qualidade técnica", "Passagem T6 → T7: mentoria formal de juniores e auditoria interna de qualidade; mínimo de 18 meses como T6"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('C1','comercial','Auxiliar de Atendimento',7,'["Função de atendimento/administrativa", "Divisão: a recepção (check-in, limpeza e organização da área de acolhimento) é avaliada pela Roberta no documento 6; aqui conta só a parte comercial do atendimento", "Recebe visitantes interessados, registra o contato e encaminha para a consultoria ou a coordenação comercial", "Apoia na recepção as campanhas e ações comerciais da coordenação", "Encaminha dúvidas de planos, cancelamentos e reclamações para a equipe comercial", "Manutenção preventiva: avisa na hora qualquer defeito que perceber na recepção ou no salão"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('C2','comercial','Consultor de Relacionamento',8,'["Foco: visitas, aula experimental, matrículas, WhatsApp e renovações", "Mínimo de 6 meses como C1, com média ≥ 4,0 em 2 ciclos", "Domina o funil completo: atendimento, visita guiada, aula experimental, matrícula e pós-venda", "Bate a meta mensal de conversão experimental → matrícula em pelo menos 2 de cada 3 meses", "Explica com segurança os planos, Wellhub, TotalPass e os diferenciais da B Fit", "Cuida da retenção: contato com alunos ausentes e registro no sistema", "Manutenção preventiva: checagem diária de salão e recepção e aviso imediato de defeito em aparelho"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('C3','comercial','Consultor Sênior / Líder de Relacionamento',9,'["Foco: funil de vendas, pós-venda, recuperação de alunos e treino do time", "Mínimo de 12 meses como C2, com média ≥ 4,0 em 2 ciclos e nenhuma nota < 3 em Cultura e ética", "Bate as metas de conversão e retenção por 6 meses seguidos e acompanha os números da própria carteira", "Treina e acompanha os C1 e os novos atendentes", "Cria e executa ao menos 1 ação comercial por semestre (campanha, parceria ou evento)", "Resolve reclamações e casos difíceis sem precisar escalar", "Manutenção preventiva: ajuda a organizar a rotina de manutenção e confere os registros da equipe"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('C4','comercial','Coordenador(a) Comercial',10,'["Responde por campanhas, parcerias e metas comerciais", "Domínio de metas de conversão e do funil", "Tempo mínimo de referência: C1 → C2 → C3 → C4 = 6 / 12 / 18 meses; metas de conversão e retenção, domínio do funil e do WhatsApp, treino de pares", "Pode haver designação direta pelo Izaque, sem tempos mínimos (ex.: Mayra, por habilidade em vendas)", "Coordena, avalia e dá as notas de C1 a C3", "Orienta, designa e avalia o serviço de marketing terceirizado prestado pelo Júlio (anexo do documento 4)", "Acima da C4: níveis de gestão próprios, conforme o planejamento do Izaque, sem passar pela estrutura de estagiários de Ed. Física"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('G1','gestao','Coordenador(a) de Salão',11,'["Foco: escalas do salão, padrão de atendimento, supervisão de estagiários e professores", "Coordena o salão de musculação", "CREF ativo", "Avalia, enquadra e dá as notas da trilha técnica T1 a T7", "Passagem Técnica/Comercial → Gestão: gestão de conflitos, liderança natural, planejamento; 90 dias acompanhando um coordenador"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('G2','gestao','Coord. Técnico / RT (CREF)',12,'["Define e garante o padrão metodológico", "Assume a responsabilidade técnica e legal (RT)", "Preparação: gestão de conflitos e liderança, planejamento do salão e dos turnos, 90 dias acompanhando um coordenador", "Responde pela qualidade técnica", "Hoje o Responsável Técnico é o Izaque"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('G3','gestao','Gerente Geral',13,'["Responde por KPIs financeiros, estratégia comercial e gestão de pessoas", "Reporte à direção"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('REC','funcao','Atendimento de Recepção',14,'["Recepção e check-in dos alunos", "Limpeza e organização da área de acolhimento", "Acolhimento comunitário: todo aluno é cumprimentado pelo nome", "Transparência: informa preços e regras sem pegadinha", "Mantém cadastros e registros de check-in em dia", "Encaminha interessados e dúvidas de planos para a equipe comercial (Mayra) e dúvidas de treino para o salão", "Manutenção preventiva: avisa na hora qualquer defeito que perceber na recepção ou no salão"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into levels(code,track,cargo,ordem,reqs) values('ADM','funcao','Auxiliar Administrativa',15,'["Função administrativa (definida pelo Izaque, out/2026)", "Organiza documentos, cadastros e registros administrativos da B Fit", "Apoia a rotina financeira e de cobrança conforme orientação da direção", "Cumpre prazos combinados e comunica pendências à Mayra", "Sigilo e transparência no trato de dados de alunos e da empresa", "Manutenção preventiva: registra e encaminha chamados de defeito de aparelhos"]'::jsonb) on conflict(code) do update set cargo=excluded.cargo,reqs=excluded.reqs,ordem=excluded.ordem,track=excluded.track;
insert into criteria values(1,'Cultura e ética',25,'Valores B Fit, acolhimento, transparência. Nota < 3 bloqueia promoção.') on conflict(id) do update set nome=excluded.nome,peso=excluded.peso,descricao=excluded.descricao;
insert into criteria values(2,'Técnica / resultado',25,'O que a função entrega (cada ficha indica o que observar).') on conflict(id) do update set nome=excluded.nome,peso=excluded.peso,descricao=excluded.descricao;
insert into criteria values(3,'Relacionamento',20,'Com alunos, colegas e liderança.') on conflict(id) do update set nome=excluded.nome,peso=excluded.peso,descricao=excluded.descricao;
insert into criteria values(4,'Manutenção preventiva de aparelhos',15,'Inspeção, registro e aviso de defeitos conforme o nível.') on conflict(id) do update set nome=excluded.nome,peso=excluded.peso,descricao=excluded.descricao;
insert into criteria values(5,'Proatividade',15,'Ver a necessidade e agir sem precisar ser pedido.') on conflict(id) do update set nome=excluded.nome,peso=excluded.peso,descricao=excluded.descricao;
